// frontend/src/components/UserMenu.js
import React, { useState, useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { useNavigate } from "react-router-dom";
import { logout } from "../features/auth/authSlice";

const UserMenu = () => {
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const { user } = useSelector((state) => state.auth);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  // Watch for logout: when user becomes null → redirect to login
  useEffect(() => {
    if (!user) {
      navigate("/login");
    }
  }, [user, navigate]);

  const handleLogout = () => {
    dispatch(logout());
    localStorage.removeItem("refresh_token"); // safe to do here
    setDropdownOpen(false); // close dropdown
  };

  if (!user) return null;

  return (
    <div style={{ position: "relative", display: "inline-block" }}>
      <div
        onClick={() => setDropdownOpen(!dropdownOpen)}
        style={{
          display: "flex",
          alignItems: "center",
          gap: "12px",
          cursor: "pointer",
          padding: "8px 16px",
          borderRadius: "12px",
          backgroundColor: dropdownOpen ? "#f5f5f5" : "transparent",
          transition: "background 0.2s",
          userSelect: "none",
        }}
      >
        <div
          style={{
            width: "42px",
            height: "42px",
            borderRadius: "50%",
            backgroundColor: "#667eea",
            color: "white",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontWeight: "bold",
            fontSize: "18px",
          }}
        >
          {user.email.charAt(0).toUpperCase()}
        </div>
        <span style={{ color: "#333", fontWeight: "500", fontSize: "15px" }}>
          {user.email}
        </span>
      </div>

      {dropdownOpen && (
        <>
          <div
            style={{ position: "fixed", inset: 0, zIndex: 9 }}
            onClick={() => setDropdownOpen(false)}
          />
          <div
            style={{
              position: "absolute",
              right: 0,
              top: "100%",
              marginTop: "10px",
              backgroundColor: "white",
              borderRadius: "12px",
              boxShadow: "0 10px 30px rgba(0, 0, 0, 0.15)",
              minWidth: "220px",
              overflow: "hidden",
              zIndex: 10,
            }}
          >
            <div
              style={{
                padding: "14px 18px",
                borderBottom: "1px solid #eee",
                fontSize: "14px",
                color: "#555",
              }}
            >
              Signed in as<br />
              <strong style={{ color: "#333" }}></strong>
            </div>
            <button
              onClick={handleLogout}
              style={{
                width: "100%",
                padding: "14px 18px",
                textAlign: "left",
                background: "none",
                border: "none",
                cursor: "pointer",
                color: "#e74c3c",
                fontWeight: "500",
                fontSize: "15px",
              }}
              onMouseOver={(e) => (e.currentTarget.style.backgroundColor = "#fdf2f2")}
              onMouseOut={(e) => (e.currentTarget.style.backgroundColor = "transparent")}
            >
              Logout
            </button>
          </div>
        </>
      )}
    </div>
  );
};

export default UserMenu;
